CREATE TABLE IF NOT EXISTS project_computers (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, runtime_provider TEXT NOT NULL, runtime_id TEXT, image TEXT NOT NULL, image_version TEXT NOT NULL, status TEXT NOT NULL, resources JSONB NOT NULL, environment_fingerprint TEXT NOT NULL DEFAULT '', readiness JSONB NOT NULL DEFAULT '[]', capabilities JSONB NOT NULL DEFAULT '[]', created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, metadata JSONB NOT NULL DEFAULT '{}');
CREATE INDEX IF NOT EXISTS project_computers_project_idx ON project_computers(project_id);
CREATE INDEX IF NOT EXISTS project_computers_status_idx ON project_computers(status);
CREATE TABLE IF NOT EXISTS project_computer_operations (id TEXT PRIMARY KEY, computer_id TEXT NOT NULL REFERENCES project_computers(id) ON DELETE CASCADE, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, operation TEXT NOT NULL, status TEXT NOT NULL, run_id TEXT, error TEXT NOT NULL DEFAULT '', started_at TIMESTAMPTZ NOT NULL, completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS runtime_capabilities (runtime_provider TEXT NOT NULL, capability TEXT NOT NULL, status TEXT NOT NULL, evidence TEXT NOT NULL DEFAULT '', checked_at TIMESTAMPTZ NOT NULL, PRIMARY KEY(runtime_provider,capability));
CREATE TABLE IF NOT EXISTS shared_tools (id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, platforms JSONB NOT NULL DEFAULT '[]', dependencies JSONB NOT NULL DEFAULT '[]', capabilities JSONB NOT NULL DEFAULT '[]', install_strategy TEXT NOT NULL, verification_strategy TEXT NOT NULL, artifact_identity TEXT NOT NULL, metadata JSONB NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS shared_tool_versions (tool_id TEXT NOT NULL REFERENCES shared_tools(id) ON DELETE CASCADE, version TEXT NOT NULL, platform TEXT NOT NULL, architecture TEXT NOT NULL, dependencies JSONB NOT NULL DEFAULT '[]', artifact_id TEXT, installation_method TEXT NOT NULL, verification_method TEXT NOT NULL, compatibility JSONB NOT NULL DEFAULT '[]', PRIMARY KEY(tool_id,version,platform,architecture));
CREATE TABLE IF NOT EXISTS shared_artifacts (id TEXT PRIMARY KEY, name TEXT NOT NULL, version TEXT NOT NULL, platform TEXT NOT NULL, architecture TEXT NOT NULL, size BIGINT NOT NULL DEFAULT 0, checksum TEXT NOT NULL, source TEXT NOT NULL, storage_location TEXT NOT NULL, metadata JSONB NOT NULL DEFAULT '{}', UNIQUE(name,version,platform,architecture,checksum));
CREATE TABLE IF NOT EXISTS global_cache_entries (artifact_id TEXT PRIMARY KEY REFERENCES shared_artifacts(id) ON DELETE RESTRICT, status TEXT NOT NULL, verified_at TIMESTAMPTZ, last_used_at TIMESTAMPTZ, ref_count INTEGER NOT NULL DEFAULT 0, storage_location TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS environment_fingerprints (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, computer_id TEXT NOT NULL REFERENCES project_computers(id) ON DELETE CASCADE, fingerprint TEXT NOT NULL, expected JSONB NOT NULL, actual JSONB NOT NULL, drift_status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS environment_capabilities (id BIGSERIAL PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, computer_id TEXT NOT NULL REFERENCES project_computers(id) ON DELETE CASCADE, capability TEXT NOT NULL, status TEXT NOT NULL, evidence TEXT NOT NULL DEFAULT '', checked_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS provisioning_resources (id BIGSERIAL PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, computer_id TEXT REFERENCES project_computers(id) ON DELETE SET NULL, kind TEXT NOT NULL, name TEXT NOT NULL, requested JSONB NOT NULL, allocated JSONB NOT NULL DEFAULT '{}', status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS shared_infrastructure_events (id BIGSERIAL PRIMARY KEY, project_id TEXT, computer_id TEXT REFERENCES project_computers(id) ON DELETE CASCADE, type TEXT NOT NULL, status TEXT NOT NULL, message TEXT NOT NULL, payload JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
